import{_ as a,o as i,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Could Ceph Become More Like a Database? - Radoslaw Zarzynski, IBM","description":"","frontmatter":{"title":"Could Ceph Become More Like a Database? - Radoslaw Zarzynski, IBM","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","分布式存储","RADOS","BlueStore","RocksDB","Native Indexing"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Could_Ceph_Become_More_Like_a_Database_-_Radoslaw_Zarzynski_IBM.md","filePath":"posts/2025/Could_Ceph_Become_More_Like_a_Database_-_Radoslaw_Zarzynski_IBM.md","lastUpdated":1780459816000}'),t={name:"posts/2025/Could_Ceph_Become_More_Like_a_Database_-_Radoslaw_Zarzynski_IBM.md"};function r(s,e,n,d,_,h){return i(),l("div",null,[...e[0]||(e[0]=[o('<h3 id="ceph会议纪要-rados原生索引概念探讨" tabindex="-1">Ceph会议纪要：RADOS原生索引概念探讨 <a class="header-anchor" href="#ceph会议纪要-rados原生索引概念探讨" aria-label="Permalink to &quot;Ceph会议纪要：RADOS原生索引概念探讨&quot;">​</a></h3><p><strong>会议基本信息</strong></p><ul><li><strong>主讲人</strong>：Radjinski（长期Ceph开发者，RADOS团队成员）</li><li><strong>会议主题</strong>：RADOS原生索引（Native Indexing）概念探讨</li><li><strong>性质</strong>：概念性讨论，非正式提案</li></ul><p><strong>核心讨论内容</strong></p><p>会议主要探讨了Ceph的RADOS原生索引概念，旨在提高存储系统的效率和可用性。</p><h4 id="历史背景与问题分析" tabindex="-1">历史背景与问题分析 <a class="header-anchor" href="#历史背景与问题分析" aria-label="Permalink to &quot;历史背景与问题分析&quot;">​</a></h4><ul><li>Ceph的OMAP（Object Map）从使用<code>std::map</code>序列化直接存储，到引入CLS T-map，再到基于LevelDB/RocksDB的现代OMAP，其演进历史展示了存储系统的不断优化。</li><li>当前OMAP的限制包括原子性缺失、客户端复杂性高以及BlueStore层OMAP隔离的人为设计限制。</li></ul><h4 id="rados-native-indexing提案" tabindex="-1">RADOS Native Indexing提案 <a class="header-anchor" href="#rados-native-indexing提案" aria-label="Permalink to &quot;RADOS Native Indexing提案&quot;">​</a></h4><ul><li>利用BlueStore底层统一的RocksDB keyspace，通过key前缀区分不同索引，保持数据与索引的共置。</li><li>新增原生索引创建/删除操作，扩展object write操作支持索引标记，支持单次原子操作替代现有3阶段协议。</li></ul><h4 id="潜在应用场景" tabindex="-1">潜在应用场景 <a class="header-anchor" href="#潜在应用场景" aria-label="Permalink to &quot;潜在应用场景&quot;">​</a></h4><ul><li>改进RGW，简化bucket index维护流程。</li><li>优化CephFS，减少目录遍历开销。</li><li>长期可能性包括类数据库查询能力和丰富的二级索引支持。</li></ul><h4 id="关键技术挑战" tabindex="-1">关键技术挑战 <a class="header-anchor" href="#关键技术挑战" aria-label="Permalink to &quot;关键技术挑战&quot;">​</a></h4><ul><li>与ordered bucket index的协调，可能影响现有的数据/元数据分离设计。</li><li>性能考量，Resharding开销增加，OSD热点风险增加。</li><li>兼容性，保持现有POOL和OBJECT作为核心抽象，不引入分布式锁等破坏现有设计原则的机制。</li></ul><h4 id="权衡分析" tabindex="-1">权衡分析 <a class="header-anchor" href="#权衡分析" aria-label="Permalink to &quot;权衡分析&quot;">​</a></h4><ul><li>优势包括简化客户端逻辑、原子性保证和性能提升潜力。</li><li>挑战包括修改多层架构、与EC pools的兼容性、Resharding成本增加、统一索引管理和可能违反现有设计哲学。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>概念验证，在BlueStore层验证统一keyspace可行性，测量索引操作对RocksDB性能影响。</li><li>RGW集成研究，评估与ordered bucket index的协同方案，分析实际工作负载下的对象大小分布。</li><li>设计细化，制定索引生命周期管理方案，确定故障恢复机制。</li><li>社区讨论，收集更多使用场景需求，评估优先级。</li></ul><p><strong>备注</strong>：本提案处于早期概念阶段，实际实现可能需要分阶段进行并优先解决RGW等关键用例的需求。</p>',18)])])}const p=a(t,[["render",r]]);export{u as __pageData,p as default};
